local function TextPane(parent)
    local pane = {scroll = UI:Scroll(parent)}
    pane.content = CreateFrame("Frame", nil, pane.scroll)
    pane.text = UI:Label(pane.content, "", 12)
    pane.text:SetPoint("TOPLEFT", 2, -2)
    pane.text:SetJustifyV("TOP")
    pane.text:SetWordWrap(true)
    local function Resize()
        local width = math.max(1, pane.scroll:GetWidth() - 4)
        pane.content:SetWidth(width)
