local function RefreshContext(self, frame)
    local context, global = self:GetContext(), {}
    if type(context) == "table" then
        for key, value in pairs(context) do if key ~= "engines" then global[key] = value end end
    else global = context end
    local blocks = {ContextBlock(global, "", 32)}
    if type(context) == "table" and type(context.engines) == "table" then
        -- Independent budgets keep a verbose engine from hiding its peer's provenance.
        for _, name in ipairs({"v1", "v2"}) do
            blocks[#blocks + 1] = ContextBlock(context.engines[name], "engines." .. name, 64)
        end
    end
    local text = table.concat(blocks, "\n")
    frame.context:SetText(text ~= "" and text or unavailable)
    frame.contextPane.resize()
end--[[APR_DIAG]]; RefreshContext = APRTrace("APR-Core/ui/NavigationBenchmark.lua:107:RefreshContext#9", RefreshContext)--[[/APR_DIAG]]

local function Render(frame, state, reason)
    local shown = frame.valid and state or {}
    frame.status:SetText("status: " .. Value(shown.status) .. " · reason: " .. Value(reason or frame.inputError or shown.reason))
    for _, name in ipairs({"v1", "v2"}) do
        local pane = frame.results[name]
        local text = EngineText(shown.engines and shown.engines[name])
        if pane.text:GetText() ~= text then pane.text:SetText(text); pane.resize() end
    end
    frame.buttons.cancel:SetEnabled(frame.active)
    frame.buttons.copy:SetEnabled(frame.valid)
end--[[APR_DIAG]]; Render = APRTrace("APR-Core/ui/NavigationBenchmark.lua:124:Render#10", Render)--[[/APR_DIAG]]

local function Detach(frame)
