local function Invalidate(self, frame)
    if frame.filling then return end
    frame.epoch = frame.epoch + 1
    local active = frame.active or self:GetState().status == "running"
    Detach(frame)
    if active then self:Cancel() end
    frame.valid = false
    frame.inputError = false
    Render(frame, {})
    for _, pane in pairs(frame.results) do pane.scroll:SetVerticalScroll(0) end
end--[[APR_DIAG]]; Invalidate = APRTrace("APR-Core/ui/NavigationBenchmark.lua:146:Invalidate#13", Invalidate)--[[/APR_DIAG]]

local function ReadInput(frame)
    local input = {startMode=frame.startMode, from={}, to={}}
    for _, side in ipairs({"from", "to"}) do
        for _, key in ipairs({"mapID", "x", "y"}) do input[side][key] = frame.inputs[side][key]:GetText() end
    end
    return input
end--[[APR_DIAG]]; ReadInput = APRTrace("APR-Core/ui/NavigationBenchmark.lua:158:ReadInput#14", ReadInput)--[[/APR_DIAG]]

local function FillSource(frame, source)
    frame.filling = true
    for _, key in ipairs({"mapID", "x", "y"}) do
        frame.inputs.from[key]:SetText(source[key] ~= nil and tostring(source[key]) or "")
    end
    frame.filling = false
end--[[APR_DIAG]]; FillSource = APRTrace("APR-Core/ui/NavigationBenchmark.lua:166:FillSource#15", FillSource)--[[/APR_DIAG]]

local function Run(self, frame, mode)
    if not frame:IsShown() then return end
    Invalidate(self, frame)
    if frame.startMode == "player" then FillSource(frame, {}) end
    local ok, reason = self:Start(ReadInput(frame), mode)
    if not ok then frame.inputError = reason or false; Render(frame, {}, reason); return end
    frame.valid = true
    frame.epoch = frame.epoch + 1
    if frame.startMode == "player" then
        local capture = self:GetCapture()
        FillSource(frame, capture and capture.from or {})
    end
    local state = self:GetState()
    frame.active = state.status == "running"
    Render(frame, state)
    RefreshContext(self, frame)
    if frame.active then frame:SetScript("OnUpdate", frame.update) end
end--[[APR_DIAG]]; Run = APRTrace("APR-Core/ui/NavigationBenchmark.lua:174:Run#16", Run)--[[/APR_DIAG]]

