function owner:Show()
    local frame = self.benchmarkFrame
    if not frame then frame = Create(self); self.benchmarkFrame = frame end
    frame:Show()
    frame:Raise()
    local state = self:GetState()
    frame.active = frame.valid and state.status == "running"
    if frame.active then frame:SetScript("OnUpdate", frame.update) else Detach(frame) end
    Render(frame, state)
    RefreshContext(self, frame)
    return frame
end--[[APR_DIAG]]; owner.Show = APRTrace("APR-Core/ui/NavigationBenchmark.lua:294:owner:Show#27", owner.Show)--[[/APR_DIAG]]
